package com.acxiom.crm.api;
import com.acxiom.crm.customer.Customer; import com.acxiom.crm.customer.CustomerRepository; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.List;
@RestController @RequestMapping("/api/customers") public class CustomerApiController {private final CustomerRepository repo;public CustomerApiController(CustomerRepository r){repo=r;}@GetMapping public List<Customer> all(){return repo.findAll();}@GetMapping("/{id}") public Customer one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Customer create(@Valid @RequestBody Customer c){if(repo.existsByEmailIgnoreCase(c.getEmail()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already exists");if(repo.existsByPhone(c.getPhone()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Phone already exists");return repo.save(c);}@PutMapping("/{id}") public Customer update(@PathVariable Long id,@Valid @RequestBody Customer c){Customer o=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(repo.existsByEmailIgnoreCase(c.getEmail())&&!o.getEmail().equalsIgnoreCase(c.getEmail()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already exists");if(repo.existsByPhone(c.getPhone())&&!o.getPhone().equals(c.getPhone()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Phone already exists");o.setName(c.getName());o.setEmail(c.getEmail());o.setPhone(c.getPhone());o.setCompany(c.getCompany());o.setStatus(c.getStatus());return repo.save(o);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.deleteById(id);} }
